coverage=[dict(objective_id=o,evidence=[dict(session_id=s['id'],task_id=t['id'],skill=t['skill']) for s in S for t in s['tasks'] if o in t['objective_ids']]) for o in dict.fromkeys(o['id'] for s in S for o in s['objectives'])]
D=dict(unit_id=plan['id'],package_file=target.name,session_ids=[s['id'] for s in S],new_lexemes=[dict(**{k:W[w][k] for k in ['id','lexeme_key','fr','ru','transcription_ru']},first_session_id=S[n-1]['id']) for w,n in FIRST.items()],reused_lexeme_keys=sorted({w['lexeme_key'] for s in S for w in s['vocabulary'] if w['id'] in OLD}),objective_coverage=coverage,
 review_targets_for_next_unit=[dict(lexeme_key=W[w]['lexeme_key'],reason=r) for w,r in [('avoir-intention-de','Вернуть прямо выраженное намерение при обращении за услугой.'),('decider-de','Различить принятое решение и ещё не выполненное действие.'),('dici-deadline','Повторить крайний срок отдельно от момента и длительности.'),('pendant-duree','Сохранить указанную длительность без подмены сроком.'),('si-condition','Вернуть условие простого плана отдельно от причины.'),('la-semaine-prochaine','Повторить будущий период при выборе даты.'),('je-voudrais','Вернуть знакомую вежливую просьбу.'),('choisir','Сохранить прежний ключ выбора при смене грамматической формы.'),('minute','Повторить знакомую единицу длительности.')]],
 checks=dict(json_parsed=False,schema_validated=False,site_preview_passed=False,browser_audio_checked=False,language_reviewed_by_human=False),
 open_issues=['Для импорта требуется A2-U04-L05 в целевой базе; текущий пакет не создаёт внешнюю зависимость.','Редактору проверить естественность простых будущих форм, выражений намерения и решения, противопоставление крайнего срока, момента и длительности, дозировку модели условия.','Прослушать браузерную озвучку prendrai / prends, regarderai, choisirai, выражения намерения, срока и сокращённого S’il. Длительность аудио и занятий не измерена.','Выполнить предпросмотр и пробное прохождение пяти занятий, включая контроль. Выборка U01–U05 не является полным подтверждением освоения всех целей или свободной речи.'],
 progress=dict(current_unit=plan['id'],prepared_session_ids=[s['id'] for s in S],user_accepted_session_ids=[],remaining_session_ids=[],next_unit_not_started='A2-U06',next_unit_title='Повседневные услуги',previous_unit='A2-U04',previous_unit_advance_authorized=True,previous_unit_import_confirmed=False),
 scope_notes=['Команда «Следующий этап» разрешает подготовку A2-U05. Принятие и импорт предыдущих пакетов не подтверждены; повторение использует полные объекты подготовленного материала.','Новые лексические значения распределены как одно, два, два, одно и ноль. Дополнительная нагрузка — выбранные формы будущего знакомых действий и один основной контраст за занятие. L05 нового обязательного материала не вводит.','Prendrai, regarderai и choisirai — новые грамматические формы прежних значений prendre-transport, regarder и choisir. Новые ключи ради времени глагола не создаются, полные прежние объекты сохраняются.','Знакомое ближайшее намерение остаётся допустимым способом говорить о будущем. Не вводится ложное абсолютное деление futur proche — всегда близко, futur simple — всегда далеко или увереннее. В грамматическом вопросе запрошена конкретная изученная форма.','Avoir l’intention de прямо называет намерение, J’ai décidé de — принятое решение. По одной будущей форме не угадывается психологическая уверенность. Принятое решение не означает уже выполненную поездку или просмотр.','D’ici midi — крайний срок не позднее полудня; à midi — момент. Pendant vingt minutes — указанная длительность просмотра, а не полная продолжительность фильма или время выбора билета.','Предлог pendant перед длительностью получает отдельный ключ от существующей связки pendant que. Старая связка и её полные карточки не переписываются. Minute сохраняет прежнее значение единицы времени.','В L04 вводится только модель реального условия Si + présent с результатом в futur simple. Перед il показано S’il. Все другие употребления si и полная система условных предложений не вводятся.','Наличие билета внутри если не утверждается как установленный факт. Условие поездки не подменяется условием просмотра при дожде; два плана не объявляются взаимоисключающими без слов текста.','В L01 повторено сравнение прошлого и настоящего A2-U04, в L03 — задержка, в L04 — изменение билета A2-U02. Повторение не подтверждает принятие прошлых пакетов или освоение материала учеником.','L05 имеет kind=checkpoint и восемь вопросов: два listening, два reading, два vocabulary, один grammar, один sentence_building. Вводная процедурная, без определений и готовых ответов контроля; public_page не содержит таблицы ответов.','В контроле представлены все пять тем: пересадка U02, фон и событие U04, багаж U01, впечатления U03, решение, срок, длительность и условие U05. Старые цели прикреплены только к заданиям с прямой проверкой соответствующего действия.','Восемь вопросов — выборка. Накопительное формальное покрытие обязательных целей проверяется по всем занятиям блока, а не объявляется полным по одному контролю. Семантическое качество требует редактора.','Все планы, поездки и рассказы вымышленные. Каждый текст задаёт собственные платформы, периоды, оценки и условия; данные другого задания не переносятся.','Все ответы выбираются или собираются из целых блоков, без обязательного свободного письма и записи голоса. Озвучка только браузером, без аудиофайлов или внешних сервисов.','Пакет содержит только текущую тему, без levels и curricula. Основной реестр, прежние пакеты и база сайта не изменялись.'])
